        We process it recursively and return a string in the format that NLTK's ``LogicParser``
        would understand.
        """
    if isinstance(nested_expression, str):
        return nested_expression
    operator = nested_expression[0]
    arguments = [self._process_nested_expression(arg) for arg in nested_expression[1:]]
    if operator == 'and':
        return f'({arguments[0]} & {arguments[1]})'
    elif operator == 'or':
        return f'({arguments[0]} | {arguments[1]})'
    elif operator == 'not':
        return f'~{arguments[0]}'
