def get_rmetric( self, mode_inv = 'svd', return_svd = False ):
        """
        Compute the Reimannian Metric
        """
    if mode_inv =='svd':
        U, S, V = np.linalg.svd(self.R)
        S_inv = np.diag(1. / S)
