def metadata_get(self, path, cached=True):
        """
        get metadata from inspect, specified by path

        :param path: list of str
        :param cached: bool, use cached version of inspect if available
        """
    if cached and self.inspect_cache is not None:
        inspect = self.inspect_cache
    else:
        inspect = self.inspect()
    metadata = inspect
    for key in path:
        metadata = metadata.get(key, None)
        if metadata is None:
            break

    return metadata

