def etm_register_write(self, register_index, value, delay=False):
        """Writes a value to an ETM register.

        Args:
          self (JLink): the ``JLink`` instance.
          register_index (int): the register to write to.
          value (int): the value to write to the register.
          delay (bool): boolean specifying if the write should be buffered.

        Returns:
          ``None``
        """
    if not isinstance(register_index, int):
        raise TypeError("register_index must be an integer")
    if not isinstance(value, int):
        raise TypeError("value must be an integer")
    if not isinstance(delay, bool):
        raise TypeError("delay must be a boolean")
    if not self.is_connected():
        raise RuntimeError("JLink is not connected")
    if not self.is_halted():
        raise RuntimeError("JLink is not halted")
    if not self.is_etm_enabled():
        raise RuntimeError("ETM is not enabled")
    if register_index < 0 or register_index > 0xFF:
        raise ValueError("register_index must be between 0 and 0xFF")
    if value < 0 or value > 0xFFFFFFFF:
        raise ValueError("value must be between 0 and 0xFFFFFFFF")
    self.jlink.ETMRegisterWrite(register_index, value, delay)

