def scroll(self, query=None, scroll='5m', size=100, unpack=True):
        """Scroll an index with the specified search query.

        Works as a generator. Will yield `size` results per iteration until all hits are returned.
        """
    if query is None:
        query = {}
    if not isinstance(query, dict):
        query = {'query': {'match': {'_all': query}}}
    if'size' not in query:
        query['size'] = size
    if'scroll' not in query:
        query['scroll'] = scroll
    if'sort' not in query:
        query['sort'] = ['_doc']
    if unpack:
        query['_source'] = True
    s = self._es.scroll(body=query, index=self.index, scroll=scroll)
    while True:
        hits = s['hits']['hits']
        if not hits:
            break
        for hit in hits:
            yield hit
        s = self._es.scroll(scroll_id=s['_scroll_id'], scroll=scroll)

