        if self.api_version == 7 and isinstance(domain, list):
            domain = ','.join(domain)

        if self.api_version in [2, 7]:
            last_updates_resp = requests.get(ENDPOINTS_BY_API_VERSION[self.api_version], params={'UPDATE': 1})
