def extract(self, obj, bypass_ref=False):
        """
        Extract subelement from obj, according to tokens.

        :param obj: the object source
        :param bypass_ref: disable JSON Reference errors
        """
    if self.tokens:
        token = self.tokens.pop(0)
        if token == "*":
            if isinstance(obj, list):
                result = []
                for item in obj:
                    result.extend(self.extract(item, bypass_ref))
                return result
            elif isinstance(obj, dict):
                result = []
                for key, value in obj.items():
                    result.extend(self.extract({key: value}, bypass_ref))
                return result
            else:
                return [obj]
        elif token.startswith("(") and token.endswith(")"):
            token = token[1:-1]
            result = []
            for sub_token in token.split(","):
                sub_token = sub_token.strip()
                result.extend(self.extract(obj.get(sub_token), bypass_ref))
            return result
        elif token.startswith("[") and token.endswith("]"):
            token = token[1:-1]
            result = []
            for sub_token in token.split(","):
                sub_token = sub_token.strip()
                if sub_token.isdigit():
                    index = int(sub_token)
                    if isinstance(obj, list) and len(obj) > index:
                        result.extend(self.extract(obj[index], bypass_ref))
                else:
                    result.extend(self.extract(obj.get(sub_token), bypass_ref))
            return result
        else:
            return self.extract(obj.get(token), bypass_ref)
    else:
        return [obj]

