def _smart_get_initialized_channel_for_service(self, metadata, filter_by, is_try_initailize = True):
        """
         - filter_by can be sender or signer
        """
    if filter_by == "sender":
        channel_id = metadata.sender
    elif filter_by == "signer":
        channel_id = metadata.signer
    else:
        raise ValueError("filter_by must be either'sender' or'signer'")

    channel = self._channels.get(channel_id)
    if channel is None and is_try_initailize:
        channel = self._initialize_channel(channel_id)

    return channel

