mgc_code:
def upload(self, fd, name=None, folder_key=None, filedrop_key=None,
               path=None, action_on_duplicate=None):
        """Upload file, returns UploadResult object

        fd -- file-like object to upload from, expects exclusive access
        name -- file name
        folder_key -- folderkey of the target folder
        path -- path to file relative to folder_key
        filedrop_key -- filedrop to use instead of folder_key
        action_on_duplicate -- skip, keep, replace
        """
    if name is None:
        name = fd.name
    if folder_key is None and filedrop_key is None:
        raise ValueError("Either folder_key or filedrop_key must be provided")
    if folder_key is not None and filedrop_key is not None:
        raise ValueError("Only one of folder_key or filedrop_key can be provided")
    if action_on_duplicate not in (None, "skip", "keep", "replace"):
        raise ValueError("Invalid value for action_on_duplicate")
    if path is not None and folder_key is None:
        raise ValueError("path can only be provided when folder_key is provided")
    if path is not None and not path.startswith("/"):
        raise ValueError("path must be absolute")
    if folder_key is not None:
        folder = self.get_folder(folder_key)
        if path is not None:
            parent_folder, name = path.rsplit("/", 1)
            parent_folder = self.get_folder(parent_folder)
        else:
            parent_folder = folder
    elif filedrop_key is not None:
        filedrop = self.get_filedrop(filedrop_key)
        parent_folder = filedrop
    if action_on_duplicate is None:
        action_on_duplicate = "skip"
    if action_on_duplicate == "skip" and name in parent_folder:
        return UploadResult(name, parent_folder, "skip")
    if action_on_duplicate == "keep" and name in parent_folder:
        name = self.get_unique_name(name, parent_folder)
    parent_folder.upload(fd, name)
    return UploadResult(name, parent_folder, "upload")

