mgc_code:
def zscore_df(df, axis='row', keep_orig=False):
  """
  take the zscore of a dataframe dictionary, does not write to net (self)
  """
    if axis == 'row':
        mean = df.mean(axis=1)
        std = df.std(axis=1)
    elif axis == 'column':
        mean = df.mean()
        std = df.std()
    zscore = (df - mean) / std
    if not keep_orig:
        return zscore
    else:
        return df, zscore

