def delete(self, deletion_point, no_to_delete, axis, tab=None):
        """Deletes no_to_delete rows/cols/... starting with deletion_point

        Axis specifies number of dimension, i.e. 0 == row, 1 == col, 2 == tab

        """
    if axis == 0:
        del self.rows[deletion_point:deletion_point + no_to_delete]
    elif axis == 1:
        for row in self.rows:
            del row[deletion_point:deletion_point + no_to_delete]
    elif axis == 2:
        del self.tabs[deletion_point:deletion_point + no_to_delete]
    else:
        raise ValueError("Invalid axis")

