        Completes in O(log n) time.
        """
        if self.root is None:
            return
        self.root = self._discard(self.root, interval)

    def _discard(self, node, interval):
        if node is None:
            return None
        if interval < node.interval:
            node.left = self._discard(node.left, interval)
        elif interval > node.interval:
            node.right = self._discard(node.right, interval)
        else:
            if node.left is None:
                return node.right
            elif node.right is None:
                return node.left
            else:
                successor = self._find_min(node.right)
                node.interval = successor.interval
                node.right = self._discard(node.right, successor.interval)
        return node

    def _find_min(self, node):
        while node.left is not None:
            node = node.left
        return node

