def STVsocwinners(self, profile):
        """
        Returns an integer list that represents all possible winners of a profile under STV rule.

        :ivar Profile profile: A Profile object that represents an election profile.
        """
    winners = []
    while len(winners) < profile.num_seats:
        highest_vote_candidate = profile.get_highest_vote_candidate()
        if highest_vote_candidate.votes >= profile.quota:
            winners.append(highest_vote_candidate.id)
        else:
            break
    return winners

