def find_executable(cls, name, check_syspaths=False):
        """Find an executable.

        Args:
            name (str): Program name.
            check_syspaths (bool): If True, check the standard system paths as
                well, if program was not found on current $PATH.

        Returns:
            str: Full filepath of executable.
        """
    path = os.environ.get("PATH")
    if path is None:
        raise OSError("PATH environment variable is not set")
    paths = path.split(os.pathsep)
    for path in paths:
        full_path = os.path.join(path, name)
        if os.access(full_path, os.X_OK):
            return full_path
    if check_syspaths:
        for path in shutil.get_exec_path():
            full_path = os.path.join(path, name)
            if os.access(full_path, os.X_OK):
                return full_path
    raise OSError(f"Executable '{name}' not found")

